const SIZE=2097152;
const from64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
async function sha(data){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',data)),b=>b.toString(16).padStart(2,'0')).join('');}
async function check(data,expected,label){let actual=await sha(data);if(actual!==expected)throw Error(label+' SHA-256 mismatch: '+actual);}
function ips(data,p){if(p.length<8||String.fromCharCode(...p.slice(0,5))!=='PATCH')throw Error('Invalid IPS');let out=data.slice(),i=5;while(i+3<=p.length){if(p[i]===69&&p[i+1]===79&&p[i+2]===70){if(i+3!==p.length)throw Error('Trailing IPS data');return out;}if(i+5>p.length)throw Error('Truncated IPS');let a=p[i]*65536+p[i+1]*256+p[i+2],n=p[i+3]*256+p[i+4];i+=5;if(n){if(i+n>p.length||a+n>out.length)throw Error('Invalid IPS range');out.set(p.subarray(i,i+n),a);i+=n;}else{if(i+3>p.length)throw Error('Truncated RLE');n=p[i]*256+p[i+1];if(!n||a+n>out.length)throw Error('Invalid RLE range');out.fill(p[i+2],a,a+n);i+=3;}}throw Error('Missing IPS EOF');}
async function validateNES(data){if(data.length!==131088||data[0]!==78||data[1]!==69||data[2]!==83||data[3]!==26)throw Error('Expected 131,088-byte iNES PRG0 image.');await check(data,manifest.input_sha256,'NES PRG0');}
async function updateMD(data,log=()=>{}){if(data.length!==SIZE)throw Error('Expected 2 MiB MD13 ROM.');await check(data,manifest.base_sha256,'MD13');for(const step of manifest.overlays){let p=from64(patches[step.file]);await check(p,step.patch_sha256,step.file);data=ips(data,p);await check(data,step.output_sha256,step.file+' output');log(step.file+' ✓');}await check(data,manifest.output_sha256,'MD35');let sum=0;for(let i=512;i<data.length;i+=2)sum=(sum+data[i]*256+data[i+1])&65535;if(String.fromCharCode(...data.slice(256,260))!=='SEGA'||sum!==data[398]*256+data[399])throw Error('Invalid Mega Drive header/checksum');return data;}

module.exports={validateNES,updateMD,ips,sha};
